      if (!b) continue                                                            // not loaded: not judged
      if (!CONTAINER_RE.test(blockNameOf(bot, b) ?? '')) { gone.push(k0); continue } // loaded, and no longer storage
      if (!inTown(home, c)) continue
      const k = containerKey(bot, c)
