const townIndexed = pos => TOWNINDEX.on && !!pos && inTown(homeVec(), pos)
const indexId = (bot, tag) => `${bot?.username ?? 'bot'}-${tag}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
