  const c = pick.cell
  try { await goto(ctx, { x: c.x, y: c.y, z: c.z, range: 3 }, signal, { until: Math.min(deadline, Date.now() + 45_000) }) } catch (e) { if (e?.aborted || signal?.aborted) throw e }
  check(signal)
