  try { await chestWalk(bot, new goals.GoalNear(tb.position.x, tb.position.y, tb.position.z, 2), Math.max(1000, Math.min(TD_WALK_MS * 2, deadline - Date.now()))) } catch (e) { if (e?.aborted || signal?.aborted) throw e }
  check(signal)
