  const heads = projectHeads().filter(x => x.plot !== WALLEXT_PLOT)
  const wh = recordHead(dir, projKeyOf(WALL_PLOT)), hh = recordHead(dir, projKeyOf(HUB_PLOT))
  if (!wh.ok || !hh.ok) throw new Error('wall or hall record unreadable')
