    Object.assign(f, extra, { outcome, why: detail, ms: Date.now() - t0 })
    try { logEvent({ kind: 'build_visit', status, snapshot: snapshot(bot), durationMs: Date.now() - t0, detail: buildVisitDetail(f) }) } catch { /* telemetry */ }
