  const land = projectHeads().filter(x => x.plot === LAND_PLOT || x.plot === SITEPREP_PLOT).map(x => x.head.rec)
  const zs = [...c.zones, ...recordZones(land), ...hallPadZones(plan), ...townMarkerZones()]
