  const find = names => { const ids = names.map(x => bot.registry?.blocksByName?.[x]?.id).filter(Number.isFinite); try { return ids.length ? bot.findBlocks?.({ matching: ids, maxDistance: GK.gatherR, count: 128 }) ?? [] : [] } catch { return [] } }
