    let s
    try { s = stepwellSite(bot, home, stepwellInputs(bot, c, h, dir), t0, me) } catch (e) { return out('no_effect', 'site_unread', `the town's records could not be read (${String(e?.message ?? e).slice(0, 60)})`, { stop: 'site_unread' }) }
