      publishRecord(dir, key, cur => (cur && cur.blueprint === STEPWELL_BLUEPRINT && !cur.site?.descent ? { ...cur, descentNone: { why: sd.why, bottom: sd.bottom, at: Date.now() } } : null), { by: me })
